import java.util.*;

class Solution {
  public long findMaximumElegance(int[][] items, int k) {
    Arrays.sort(items, (a, b) -> Integer.compare(b[0], a[0]));
    long sum = 0, ans = 0;
    Set<Integer> categories = new HashSet<>();
    PriorityQueue<Integer> duplicates = new PriorityQueue<>();
    for (int i = 0; i < k; i++) {
      sum += items[i][0];
      if (!categories.add(items[i][1])) duplicates.add(items[i][0]);
    }
    ans = sum + (long) categories.size() * categories.size();
    for (int i = k; i < items.length && !duplicates.isEmpty(); i++)
      if (categories.add(items[i][1])) {
        sum += items[i][0] - duplicates.remove();
        ans = Math.max(ans, sum + (long) categories.size() * categories.size());
      }
    return ans;
  }
}
